"""Execute native mission selection for every named PAL/US level-table row.

This covers GameNewMission, InitialiseSingleGame's direct-level lookup, and
the mission initializers. Inputs select a level; expected mission ids and
allocation sizes come from executed native instructions, not the port.
No retail code or assets are emitted.
"""
import argparse
import hashlib
import json
from pathlib import Path

from generate_heap_reference import LoaderMachine, select_mission, NTSC_SEGMENT_SHA
from generate_resource_reference import SEGMENT_SHA


def run(image, ntsc):
    rows = []
    for index in range(64):
        m = LoaderMachine(image, None, ntsc)
        m.call(0x8006E8C0)
        table = m.address(0x8009C6C8)
        row = table + 56 * index
        if not m.read(row, 4):  # The native lookup's empty-name sentinel.
            break
        m.write(m.address(0x800B2F94), 4, table)
        display = bytes(m.mem[(row & 0x1FFFFFFF):(row & 0x1FFFFFFF) + 12]).split(b'\0')[0].decode('ascii')
        record = select_mission(m, row)
        pointer = m.read(m.address(0x800B2A30), 4)
        rows.append({'index': index, 'display': display,
                     'directory': m.string(row + 12),
                     'mission': m.read(m.address(0x800B2E20), 4),
                     'record': record, 'bytes': m.read(pointer - 20, 4) if pointer else 0})
    else:
        raise ValueError('Missing level-table sentinel')
    # All selectors, including the distinct Tribute and null-mission arms.
    selectors = []
    m = LoaderMachine(image, None, ntsc)
    m.call(0x8006E8C0)
    for selector in (0, 1, 2, 3, 4, 5, 6, 7, 5, 0, 7):
        m.put(m.address(0x800E46CC), bytes(12))
        m.put(m.address(0x800E46C0), bytes(12))
        m.write(m.address(0x800B2D7C), 4, selector)
        m.call(0x8003F37C)
        pointer = m.read(m.address(0x800B2A30), 4)
        selectors.append({'input': selector, 'mission': m.read(m.address(0x800B2E20), 4),
                          'next_mission': m.read(m.address(0x800B2D7C), 4),
                          'name': m.string(m.address(0x800E46C0)),
                          'bytes': m.read(pointer - 20, 4) if pointer else 0,
                          'heap': m.snapshot()})
    return {'rows': rows, 'selectors': selectors}


def header(pal_rows, ntsc_rows):
    lines = ['/* Native PAL/US direct-level mission selection; no retail code/assets.',
             f' * PAL SHA-256: {SEGMENT_SHA}', f' * US SHA-256: {NTSC_SEGMENT_SHA}',
             ' * Generated by generate_mission_reference.py. */',
             'static const struct level_mission_reference {',
             '    const char *display, *display_ntsc, *directory;',
             '    unsigned mission, record_bytes;',
             '} level_mission_reference[] = {']
    for row, ntsc in zip(pal_rows, ntsc_rows):
        if {k: v for k, v in row.items() if k != 'display'} != {k: v for k, v in ntsc.items() if k != 'display'}:
            raise ValueError('PAL and US mission choices differ; separate fixtures required')
        if row['mission'] != row['record']:
            raise ValueError('Direct-level selector and allocated record disagree')
        lines.append('    {' + json.dumps(row['display']) + ', ' + json.dumps(ntsc['display']) + ', ' + json.dumps(row['directory'])
                     + f', {row["mission"]}u, {row["bytes"]}u' + '},')
    return '\n'.join(lines + ['};', ''])


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('pal_segment', type=Path)
    parser.add_argument('ntsc_segment', type=Path)
    parser.add_argument('header', type=Path)
    parser.add_argument('--output', type=Path, required=True)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    evidence = {}
    for key, path, sha, ntsc in [('pal', args.pal_segment, SEGMENT_SHA, False),
                                 ('ntsc', args.ntsc_segment, NTSC_SEGMENT_SHA, True)]:
        image = path.read_bytes()
        if hashlib.sha256(image).hexdigest() != sha:
            raise ValueError(f'Expected verified {key} segment')
        evidence[key] = run(image, ntsc)
    args.output.write_text(json.dumps(evidence, indent=2) + '\n', encoding='utf-8')
    content = header(evidence['pal']['rows'], evidence['ntsc']['rows'])
    if args.check:
        if args.header.read_text(encoding='utf-8') != content:
            raise ValueError('Stored mission fixture differs from native execution')
    else:
        args.header.write_text(content, encoding='utf-8')
    print('102 direct-level selections and 22 retained selector calls executed; PAL/US choices match')


if __name__ == '__main__':
    main()
